SELECT * FROM (SELECT e.event_id,'P:'||s.plate_id case_id,e.activity,e.timestamp FROM (SELECT 'DIM:'||inspection_id event_id,'Dimensional Inspection Completed' activity,inspected_at timestamp,inspection_id source_key FROM dimension_inspection WHERE inspected_at IS NOT NULL AND (1=1)) e JOIN dimension_inspection s ON s.inspection_id=e.source_key JOIN plate_material piece ON piece.plate_id=s.plate_id JOIN as_rolled_material m ON m.material_id=piece.mother_material_id UNION ALL SELECT e.event_id,'P:'||s.plate_id case_id,e.activity,e.timestamp FROM (SELECT 'REV:'||review_id event_id,'Plate Quality Review Completed' activity,finished_at timestamp,review_id source_key FROM plate_quality_review WHERE finished_at IS NOT NULL AND (1=1)) e JOIN plate_quality_review s ON s.review_id=e.source_key JOIN plate_material piece ON piece.plate_id=s.plate_id JOIN as_rolled_material m ON m.material_id=piece.mother_material_id) ORDER BY case_id,timestamp,event_id;
